### https://github.com/acme/aidenhq/pull/41
diff --git a/modules/slack/connections/slack-mcp/src/search.ts b/modules/slack/connections/slack-mcp/src/search.ts
index 4b5c6d7..8e9f0a1 100644
--- a/modules/slack/connections/slack-mcp/src/search.ts
+++ b/modules/slack/connections/slack-mcp/src/search.ts
@@ -31,6 +31,13 @@ export function searchArgs(input: SearchInput): SlackSearchArgs {
   const args: SlackSearchArgs = { query: input.query, filters: input.filters ?? [] };
+  // Slack parses emoji-reaction modifiers only from the query; in `filters` they are silently dropped.
+  const emoji = args.filters.filter((f) => /^has(my)?::[\w+-]+:$/.test(f));
+  if (emoji.length) {
+    args.query = [args.query, ...emoji].filter(Boolean).join(" ");
+    if (input.natural_language_query) args.natural_language_query = [input.natural_language_query, ...emoji].join(" ");
+  }
   return args;
 }
diff --git a/modules/slack/connections/slack-mcp/test/search.test.ts b/modules/slack/connections/slack-mcp/test/search.test.ts
index 2c3d4e5..6f7a8b9 100644
--- a/modules/slack/connections/slack-mcp/test/search.test.ts
+++ b/modules/slack/connections/slack-mcp/test/search.test.ts
@@ -18,3 +18,10 @@ test("plain filters pass through", () => {
   assert.deepEqual(searchArgs({ query: "deploy", filters: ["in:#eng"] }).filters, ["in:#eng"]);
 });
+
+test("emoji-reaction filters are repeated in the query", () => {
+  const a = searchArgs({ query: "", filters: ["hasmy::eyes:", "in:#eng"] });
+  assert.equal(a.query, "hasmy::eyes:");
+  assert.deepEqual(a.filters, ["hasmy::eyes:", "in:#eng"]);
+});
